test_that("standata handles the 'subset' addition argument correctly", {
  brms_setup("standata:246",
    dat1 <- data.frame(
      y1 = rnorm(15), y2 = NA,
      x1 = rnorm(15), x2 = NA, x3 = rnorm(15),
      sub1 = 1, sub2 = 0
    )
  )
  brms_setup("standata:251",
    dat2 <- data.frame(
      y1 = NA, y2 = rnorm(10),
      x1 = NA, x2 = rnorm(10), x3 = NA,
      sub1 = 0, sub2 = 1
    )
  )
  brms_setup("standata:256",
    dat <- rbind(dat1, dat2)
  )
  brms_setup("standata:258",
    bform <-
      bf(y1 | subset(sub1) ~ x1*x3 + sin(x1), family = gaussian()) +
      bf(y2 | subset(sub2) ~ x2, family = gaussian()) +
      set_rescor(FALSE)
  )
  brms_setup("standata:263",
    sdata <- standata(bform, dat)
  )
  brms_setup("standata:264",
    nsub1 <- sum(dat$sub1)
  )
  brms_setup("standata:265",
    nsub2 <- sum(dat$sub2)
  )
  brms_port("standata:266", "cannot transfer",
    "frmtmb has no subset() addition term",
    expect_equal(sdata$N_y1, nsub1)
  )
  brms_port("standata:267", "cannot transfer",
    "frmtmb has no subset() addition term",
    expect_equal(sdata$N_y2, nsub2)
  )
  brms_port("standata:268", "cannot transfer",
    "frmtmb has no subset() addition term",
    expect_equal(length(sdata$Y_y1), nsub1)
  )
  brms_port("standata:269", "cannot transfer",
    "frmtmb has no subset() addition term",
    expect_equal(nrow(sdata$X_y2), nsub2)
  )
})

test_that("standata allows to retrieve the initial data order", {
  brms_setup("standata:305",
    dat <- data.frame(y1 = rnorm(100), y2 = rnorm(100),
                            id = sample(1:10, 100, TRUE),
                            time = sample(1:100, 100))
  )
  brms_setup("standata:309",
    sdata1 <- standata(y1 ~ ar(time, id), data = dat, internal = TRUE)
  )
  brms_port("standata:310", "cannot transfer",
    paste0(
      "reads brms's internal old_order attribute of Stan data, ",
      "which exists because brms sorts rows for its ",
      "autocorrelation code; frmtmb keeps the data order and has ",
      "no such attribute. The setup ar(time, id) runs (brms's cov ",
      "= FALSE form, ?frmtmb-autocor)"),
    expect_equal(dat$y1, as.numeric(sdata1$Y[attr(sdata1, "old_order")]))
  )
  brms_setup("standata:313",
    form <- bf(mvbind(y1, y2) ~ ma(time, id)) + set_rescor(FALSE)
  )
  brms_setup("standata:314",
    sdata2 <- standata(form, data = dat, internal = TRUE)
  )
  brms_port("standata:315", "cannot transfer",
    paste0(
      "reads brms's internal old_order attribute of Stan data; ",
      "frmtmb keeps the data order and has no such attribute. The ",
      "setup ma(time, id) runs (?frmtmb-autocor)"),
    expect_equal(sdata2$Y_y1[attr(sdata2, "old_order")], as.array(dat$y1))
  )
  brms_port("standata:316", "cannot transfer",
    paste0(
      "reads brms's internal old_order attribute of Stan data; ",
      "frmtmb keeps the data order and has no such attribute. The ",
      "setup ma(time, id) runs (?frmtmb-autocor)"),
    expect_equal(sdata2$Y_y2[attr(sdata2, "old_order")], as.array(dat$y2))
  )
})

test_that("standata handles 'mi' terms with 'subset'", {
  brms_setup("standata:610",
    dat <- data.frame(
      y = rnorm(10), x = c(rnorm(9), NA), z = rnorm(10),
      g1 = sample(1:5, 10, TRUE), g2 = 10:1, g3 = 1:10,
      s = c(FALSE, rep(TRUE, 9))
    )
  )
  brms_setup("standata:616",
    bform <- bf(y ~ mi(x, idx = g1)) +
      bf(x | mi() + index(g2) + subset(s)  ~ 1) +
      set_rescor(FALSE)
  )
  brms_setup("standata:619",
    sdata <- standata(bform, dat)
  )
  brms_port("standata:620", "cannot transfer",
    paste0(
      "frmtmb has no mi(x, idx = ) and no subset() or index() ",
      "addition terms"),
    expect_true(all(sdata$idxl_y_x_1 %in% 9:5))
  )
  brms_setup("standata:631",
    bform <- bf(y ~ mi(x, idx = g1)) +
      bf(x | mi() + subset(s) ~ 1) +
      set_rescor(FALSE)
  )
  brms_port("standata:634", "cannot transfer",
    paste0(
      "frmtmb has no mi(x, idx = ); the call is refused on that, ",
      "before the index() check brms asserts"),
    expect_error(standata(bform, dat),
      "Response 'x' needs to have an 'index' addition term"
    )
  )
  brms_setup("standata:638",
    bform <- bf(y ~ mi(x)) +
      bf(x | mi() + subset(s) + index(g2)  ~ 1) +
      set_rescor(FALSE)
  )
  brms_port("standata:641", "cannot transfer",
    "frmtmb has no subset() addition term",
    expect_error(standata(bform, dat),
      "mi() terms of subsetted variables require the 'idx' argument",
      fixed = TRUE
    )
  )
  brms_setup("standata:646",
    bform <- bf(y | mi() ~ mi(x, idx = g1)) +
      bf(x | mi() + subset(s) + index(g2)  ~ mi(y)) +
      set_rescor(FALSE)
  )
  brms_port("standata:649", "cannot transfer",
    "frmtmb has no mi(x, idx = ) and no subset() addition term",
    expect_error(standata(bform, dat),
      "mi() terms in subsetted formulas require the 'idx' argument",
      fixed = TRUE
    )
  )
})

test_that("by variables in grouping terms are handled correctly", {
  brms_setup("standata:691",
    gvar <- c("1A", "1B", "2A", "2B", "3A", "3B", "10", "100", "2", "3")
  )
  brms_setup("standata:692",
    gvar <- rep(gvar, each = 10)
  )
  brms_setup("standata:693",
    g_order <- order(gvar)
  )
  brms_setup("standata:694",
    byvar <- c(0, 4.5, 3, 2, "x 1")
  )
  brms_setup("standata:695",
    byvar <- factor(rep(byvar, each = 20))
  )
  brms_setup("standata:696",
    dat <- data.frame(
      y = rnorm(100), x = rnorm(100),
      g = gvar,
      g2 = gvar[g_order],
      z = byvar,
      z2 = byvar[g_order],
      z3 = factor(1:2)
    )
  )
  brms_setup("standata:704",
    sdata <- standata(y ~ x + (x | gr(g, by = z)), dat)
  )
  brms_port("standata:705", "cannot transfer",
    paste0(
      "frmtmb's gr() takes cov and prec only, not by ",
      "(dev/brms-suite-audit.md section 5); Nby_1 is also Stan ",
      "data"),
    expect_equal(sdata$Nby_1, 5)
  )
  brms_port("standata:706", "cannot transfer",
    paste0(
      "frmtmb's gr() takes cov and prec only, not by; Jby_1 is ",
      "also Stan data"),
    expect_equal(sdata$Jby_1, as.array(c(2, 2, 1, 1, 5, 4, 4, 5, 3, 3)))
  )
  brms_setup("standata:708",
    sdata <- standata(y ~ x + (x | mm(g, g2, by = cbind(z, z2))), dat)
  )
  brms_port("standata:709", "cannot transfer",
    "frmtmb's mm() refuses by = by name",
    expect_equal(sdata$Nby_1, 5)
  )
  brms_port("standata:710", "cannot transfer",
    "frmtmb's mm() refuses by = by name",
    expect_equal(sdata$Jby_1, as.array(c(2, 2, 1, 1, 5, 4, 4, 5, 3, 3)))
  )
  brms_port("standata:712", "cannot transfer",
    paste0(
      "frmtmb's gr() takes no by, so the level check brms asserts ",
      "is never reached"),
    expect_error(standata(y ~ x + (1|gr(g, by = z3)), dat),
                 "Some levels of 'g' correspond to multiple levels of 'z3'")
  )
})

