      "3) and keeps the constant in its parameter map, not in a ",
      "data slot"),
    expect_equal(standata(bf(y ~ 1, nu = 3), dat, student())$nu, 3)
  )
  brms_port("standata:725", "cannot transfer",
    paste0(
      "reads the Stan data slot disc, which brms passes as the ",
      "constant 1; frmtmb's acat() has no disc data"),
    expect_equal(standata(y ~ 1, dat, acat())$disc, 1)
  )
  brms_port_own("standata:726",
    "not available for family 'gaussian': bias",
    "brms: Invalid fixed parameters: 'bias'",
    expect_error(standata(bf(y ~ 1, bias = 0.5), dat),
                 "Invalid fixed parameters: 'bias'")
  )
})

test_that("Cell-mean coding can be disabled", {
  brms_setup("standata:731",
    df <- data.frame(y = 1:10, g = rep(c("a", "b"), 5))
  )
  brms_setup("standata:732",
    bform <- bf(y ~ g) +
      lf(disc ~ 0 + g + (0 + g | y), cmc = FALSE) +
      cumulative()
  )
  brms_setup("standata:736",
    sdata <- standata(bform, df)
  )
  brms_setup("standata:737",
    target <- matrix(rep(0:1, 5), dimnames = list(1:10, "gb"))
  )
  brms_port("standata:738", "cannot transfer",
    paste0(
      "lf() takes no cmc argument; frmtmb refuses it with the ",
      "misleading 'lf() takes two-sided formulas', and X_disc and ",
      "Z_1_disc_1 are Stan data"),
    expect_equal(sdata$X_disc, target)
  )
  brms_port("standata:739", "cannot transfer",
    "lf() takes no cmc argument, and Z_1_disc_1 is Stan data",
    expect_equal(unname(sdata$Z_1_disc_1), as.array(rep(0:1, 5)))
  )
  brms_port("standata:740", "cannot transfer",
    "lf() takes no cmc argument",
    expect_true(!"Z_1_disc_2" %in% names(sdata))
  )
  brms_setup("standata:742",
    bform <- bf(y ~ 0 + g + (1 | y), cmc = FALSE)
  )
  brms_setup("standata:743",
    sdata <- standata(bform, df)
  )
  brms_port("standata:744", "cannot transfer",
    "bf() takes no cmc argument",
    expect_equal(sdata$X, target)
  )
  brms_port("standata:745", "cannot transfer",
    "bf() takes no cmc argument, and Z_1_1 is Stan data",
    expect_equal(unname(sdata$Z_1_1), as.array(rep(1, 10)))
  )
})

test_that("dots in formula are correctly expanded", {
  brms_setup("standata:926",
    dat <- data.frame(y = 1:10, x1 = 1:10, x2 = 1:10)
  )
  brms_setup("standata:927",
    sdata <- standata(y ~ ., dat)
  )
  brms_port("standata:928", "defect",
    paste0(
      "y ~ . is not expanded: frm() dies with R's ''.' in formula ",
      "and no data argument' on the fit route and the frame route ",
      "alike, where brms expands the dot against the data ",
      "(dev/brmsport-probe3.R)"),
    expect_equal(colnames(sdata$X), c("Intercept", "x1", "x2"))
  )
})

test_that("reserved variables 'Intercept' is handled correctly", {
  brms_setup("standata:969",
    dat <- data.frame(y = 1:10)
  )
  brms_port("standata:970", "cannot transfer",
    paste0(
      "frmtmb has no reserved Intercept variable, so 0 + intercept ",
      "dies with R's object 'intercept' not found"),
    expect_warning(
      sdata <- standata(y ~ 0 + intercept, dat),
      "Reserved variable name 'intercept' is deprecated."
    )
  )
  brms_port("standata:974", "cannot transfer",
    "frmtmb has no reserved intercept variable",
    expect_true(all(sdata$X[, "intercept"] == 1))
  )
  brms_setup("standata:975",
    sdata <- standata(y ~ 0 + Intercept, dat)
  )
  brms_port("standata:976", "cannot transfer",
    paste0(
      "frmtmb has no reserved Intercept variable: y ~ 0 + ",
      "Intercept dies with R's object 'Intercept' not found"),
    expect_true(all(sdata$X[, "Intercept"] == 1))
  )
})

test_that("standata handles addition term 'rate' is correctly", {
