  )
})

test_that("standata handles grouped ordinal thresholds correctly", {
  brms_setup("standata:1051",
    dat <- data.frame(
      y = c(1:5, 1:4, 4),
      gr = rep(c("a", "b"), each = 5),
      th = rep(5:6, each = 5),
      x = rnorm(10)
    )
  )
  brms_setup("standata:1059",
    sdata <- standata(y ~ x, dat, cumulative())
  )
  brms_port("standata:1060", "pass",
    "",
    expect_equal(sdata$nthres, 4)
  )
  brms_setup("standata:1062",
    sdata <- standata(y | thres(5) ~ x, dat, cumulative())
  )
  brms_port("standata:1063", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term ",
      "(dev/brms-suite-audit.md section 5)"),
    expect_equal(sdata$nthres, 5)
  )
  brms_port("standata:1065", "cannot transfer",
    "frmtmb has no thres() addition term",
    expect_error(
      standata(y | thres(th) ~ x, dat, cumulative()),
      "Number of thresholds needs to be a single value"
    )
  )
  brms_setup("standata:1071",
    sdata <- standata(y | thres(th, gr) ~ x, dat, cumulative())
  )
  brms_port("standata:1072", "cannot transfer",
    "frmtmb has no thres() addition term",
    expect_equal(sdata$nthres, as.array(c(5, 6)))
  )
  brms_port("standata:1073", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term; ngrthres is also Stan ",
      "data"),
    expect_equal(sdata$ngrthres, 2)
  )
  brms_port("standata:1074", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term; Jthres is also Stan ",
      "data"),
    expect_equal(unname(sdata$Jthres[1, ]), c(1, 5))
  )
  brms_port("standata:1075", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term; Jthres is also Stan ",
      "data"),
    expect_equal(unname(sdata$Jthres[10, ]), c(6, 11))
  )
  brms_setup("standata:1077",
    sdata <- standata(y | thres(gr = gr) ~ x, dat, cumulative())
  )
  brms_port("standata:1078", "cannot transfer",
    "frmtmb has no thres() addition term",
    expect_equal(sdata$nthres, as.array(c(4, 3)))
  )
  brms_port("standata:1079", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term; ngrthres is also Stan ",
      "data"),
    expect_equal(sdata$ngrthres, 2)
  )
  brms_setup("standata:1081",
    sdata <- standata(y | thres(6, gr = gr) ~ x, dat, cumulative())
  )
  brms_port("standata:1082", "cannot transfer",
    "frmtmb has no thres() addition term",
    expect_equal(sdata$nthres, as.array(c(6, 6)))
  )
  brms_port("standata:1083", "cannot transfer",
    paste0(
      "frmtmb has no thres() addition term; ngrthres is also Stan ",
      "data"),
    expect_equal(sdata$ngrthres, 2)
  )
})

test_that("NAs are allowed in unused interval censoring variables", {
  brms_setup("standata:1110",
    dat <- data.frame(y = rnorm(10), ce = c(1, rep(2, 9)))
  )
  brms_setup("standata:1111",
    dat$y2 <- dat$y + 2
  )
  brms_setup("standata:1112",
    dat$y2[1] <- NA
  )
  brms_setup("standata:1113",
    sdata <- standata(y | cens(ce, y2 = y2) ~ 1, data = dat)
  )
  brms_port("standata:1114", "pass",
    "",
    expect_equal(sdata$N, 10L)
  )
  brms_port("standata:1115", "pass",
    "",
    expect_equal(sdata$rcens[1], 0)
  )
  brms_setup("standata:1117",
    dat$ce[1] <- 2
  )
  brms_port_own("standata:1118",
    paste0(
      "cens[(][)] upper bounds must not be NA on interval-censored ",
      "rows"),
    paste0(
      "brms: 'y2' should not be NA for interval censored ",
      "observations"),
    expect_error(
      standata(y | cens(ce, y2 = y2) ~ 1, data = dat),
      "'y2' should not be NA for interval censored observations"
    )
  )
})

test_that("drop_unused_factor levels works correctly", {
  brms_setup("standata:1125",
    dat <- data.frame(y = rnorm(10), x = factor(c("a", "b"), levels = c("a", 
        "b", "c")))
  )
  brms_setup("standata:1128",
    sdata <- standata(y ~ x, data = dat)
  )
  brms_port("standata:1129", "pass",
    "",
    expect_equal(colnames(sdata$X), c("Intercept", "xb"))
  )
  brms_setup("standata:1132",
    sdata <- standata(y ~ x, data = dat, drop_unused_levels = FALSE)
  )
  brms_port("standata:1133", "cannot transfer",
    paste0(
      "frm() takes no drop_unused_levels argument; the unused ",
      "level is always dropped"),
    expect_equal(colnames(sdata$X), c("Intercept", "xb", "xc"))
  )
})
